<?php $pageTitle='Teacher Dashboard';$active='dashboard';require_once __DIR__.'/../includes/auth.php';require_role('teacher');require_once __DIR__.'/../includes/ui.php';$id=(int)user()['id'];$st=$pdo->prepare('SELECT COUNT(*) FROM courses WHERE teacher_id=?');$st->execute([$id]);$courses=(int)$st->fetchColumn();$st=$pdo->prepare('SELECT COUNT(DISTINCT e.student_id) FROM enrollments e JOIN courses c ON c.id=e.course_id WHERE c.teacher_id=?');$st->execute([$id]);$students=(int)$st->fetchColumn();$st=$pdo->prepare('SELECT COUNT(*) FROM submissions s JOIN assignments a ON a.id=s.assignment_id JOIN courses c ON c.id=a.course_id WHERE c.teacher_id=? AND s.status IN (\'submitted\',\'late\')');$st->execute([$id]);$pending=(int)$st->fetchColumn();$st=$pdo->prepare("SELECT COUNT(*) FROM assignments a JOIN courses c ON c.id=a.course_id WHERE c.teacher_id=? AND a.status='open'");$st->execute([$id]);$assignments=(int)$st->fetchColumn();$st=$pdo->prepare('SELECT c.*,COUNT(e.id) learners FROM courses c LEFT JOIN enrollments e ON e.course_id=c.id WHERE c.teacher_id=? GROUP BY c.id ORDER BY c.updated_at DESC LIMIT 5');$st->execute([$id]);$rows=$st->fetchAll();include __DIR__.'/../includes/app_start.php';?>
<div class="page-header"><div><div class="section-kicker mb-2">Faculty space</div><h1>Teacher Dashboard</h1><p>Create learning content, review student work, and track your courses.</p></div><a href="course-form.php" class="btn btn-primary"><i class="bi bi-plus-circle me-1"></i>New Course</a></div><div class="row g-3 mb-4"><div class="col-6 col-xl-3"><?=statCard('collection','Courses',$courses,'primary')?></div><div class="col-6 col-xl-3"><?=statCard('people','Students',$students,'success')?></div><div class="col-6 col-xl-3"><?=statCard('inbox','Pending Reviews',$pending,'warning')?></div><div class="col-6 col-xl-3"><?=statCard('file-earmark-text','Open Assignments',$assignments,'primary')?></div></div><div class="card p-4"><div class="d-flex justify-content-between mb-3"><div><h4 class="mb-1">My courses</h4><div class="small text-muted">Recently updated courses</div></div><a href="courses.php" class="small">Manage all</a></div><div class="table-responsive"><table class="table"><thead><tr><th>Course</th><th>Status</th><th>Learners</th><th>Updated</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><div class="fw-semibold"><?=e($r['title'])?></div><div class="small text-muted"><?=e($r['level'])?> · <?=e((string)$r['duration_hours'])?> hrs</div></td><td><?=badgeSoft(ucfirst($r['status']),$r['status']==='published'?'success':($r['status']==='pending'?'warning':'secondary'))?></td><td><?=e($r['learners'])?></td><td><?=e(date('d M Y',strtotime($r['updated_at'])))?></td><td><a class="btn btn-sm btn-light" href="course-content.php?course_id=<?=$r['id']?>">Manage</a></td></tr><?php endforeach;?></tbody></table></div></div>
<?php include __DIR__.'/../includes/app_end.php'; ?>
